  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    ccxt::any symbol = this->safeSymbol(ccxt::any{}, market);
    ccxt::any timestamp = this->safeInteger(ticker, std::string("timestamp"));
    ccxt::any last = this->safeString(ticker, std::string("last"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString(ticker, std::string("high"))},
            {std::string("low"), this->safeString(ticker, std::string("low"))},
            {std::string("bid"), this->safeString(ticker, std::string("buy"))},
            {std::string("bidVolume"), ccxt::any{}},
            {std::string("ask"), this->safeString(ticker, std::string("sell"))},
            {std::string("askVolume"), ccxt::any{}},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"), ccxt::any{}},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), ccxt::any{}},
            {std::string("change"), ccxt::any{}},
            {std::string("percentage"), ccxt::any{}},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"),
             this->safeString(ticker, std::string("vol"))},
            {std::string("quoteVolume"), ccxt::any{}},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name bitbank#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://github.com/bitbankinc/bitbank-api-docs/blob/38d6d7c6f486c793872fd4b4087a0d090a04cd0a/public-api.md#ticker
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = awaitValue(
                     this->publicGetPairTicker(this->extend(request, params)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 return this->parseTicker(data, market);
               })
        .share();
  }

  /**
   * @method
   * @name bitbank#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see
   * https://github.com/bitbankinc/bitbank-api-docs/blob/38d6d7c6f486c793872fd4b4087a0d090a04cd0a/public-api.md#depth
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = awaitValue(
                     this->publicGetPairDepth(this->extend(request, params)));
                 ccxt::any orderbook = this->safeValue(
                     response, std::string("data"), ccxt::dict{});
                 ccxt::any timestamp =
                     this->safeInteger(orderbook, std::string("timestamp"));
                 return this->parseOrderBook(
                     orderbook, ::getValue(market, std::string("symbol")),
                     timestamp);
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchTrades
    //
    //    {
    //        "transaction_id": "1143247037",
    //        "side": "buy",
    //        "price": "3836025",
    //        "amount": "0.0005",
    //        "executed_at": "1694249441593"
    //    }
    //
    ccxt::any timestamp = this->safeInteger(trade, std::string("executed_at"));
    market = this->safeMarket(ccxt::any{}, market);
    ccxt::any priceString = this->safeString(trade, std::string("price"));
    ccxt::any amountString = this->safeString(trade, std::string("amount"));
    ccxt::any id = this->safeString2(trade, std::string("transaction_id"),
                                     std::string("trade_id"));
    ccxt::any takerOrMaker =
        this->safeString(trade, std::string("maker_taker"));
    ccxt::any fee = ccxt::any{};
    ccxt::any feeCostString =
        this->safeString(trade, std::string("fee_amount_quote"));
    if (isTrue(!isEqual(feeCostString, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("currency"), ::getValue(market, std::string("quote"))},
          {std::string("cost"), feeCostString},
      };
    }
    ccxt::any orderId = this->safeString(trade, std::string("order_id"));
    ccxt::any type = this->safeString(trade, std::string("type"));
    ccxt::any side = this->safeString(trade, std::string("side"));
    return this->safeTrade(
        ccxt::dict{
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("id"), id},
            {std::string("order"), orderId},
            {std::string("type"), type},
            {std::string("side"), side},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), fee},
            {std::string("info"), trade},
        },
        market);
  }

  /**
   * @method
   * @name bitbank#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see
   * https://github.com/bitbankinc/bitbank-api-docs/blob/38d6d7c6f486c793872fd4b4087a0d090a04cd0a/public-api.md#transactions
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("pair"),
                             ::getValue(market, std::string("id"))},
                        };
                        ccxt::any response =
                            awaitValue(this->publicGetPairTransactions(
                                this->extend(request, params)));
                        ccxt::any data = this->safeValue(
                            response, std::string("data"), ccxt::dict{});
                        ccxt::any trades = this->safeList(
                            data, std::string("transactions"), ccxt::list{});
                        return this->parseTrades(trades, market, since, limit);
                      })
        .share();
  }

  /**
   * @method
   * @name bitbank#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see
   * https://github.com/bitbankinc/bitbank-api-docs/blob/38d6d7c6f486c793872fd4b4087a0d090a04cd0a/rest-api.md#get-all-pairs-info
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<ccxt::any>
  fetchTradingFees(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any response =
                     awaitValue(this->marketsGetSpotPairs(params));
                 //
                 //     {
                 //         "success": "1",
                 //         "data": {
                 //           "pairs": [
                 //             {
                 //               "name": "btc_jpy",
                 //               "base_asset": "btc",
                 //               "quote_asset": "jpy",
                 //               "maker_fee_rate_base": "0",
                 //               "taker_fee_rate_base": "0",
                 //               "maker_fee_rate_quote": "-0.0002",
                 //               "taker_fee_rate_quote": "0.0012",
                 //               "unit_amount": "0.0001",
                 //               "limit_max_amount": "1000",
                 //               "market_max_amount": "10",
                 //               "market_allowance_rate": "0.2",
                 //               "price_digits": "0",
                 //               "amount_digits": "4",
                 //               "is_enabled": true,
                 //               "stop_order": false,
                 //               "stop_order_and_cancel": false
                 //             },
                 //             ...
                 //           ]
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeValue(response, std::string("data"),
                                                  ccxt::dict{});
                 ccxt::any pairs =
                     this->safeValue(data, std::string("pairs"), ccxt::list{});
                 ccxt::any result = ccxt::dict{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(pairs));
                      postFixIncrement(i)) {
                   ccxt::any pair = ::getValue(pairs, i);
                   ccxt::any marketId =
                       this->safeString(pair, std::string("name"));
                   ccxt::any market = this->safeMarket(marketId);
                   ccxt::any symbol = ::getValue(market, std::string("symbol"));
                   ::setValue(
                       result, symbol,
                       ccxt::dict{
                           {std::string("info"), pair},
                           {std::string("symbol"), symbol},
                           {std::string("maker"),
                            this->safeNumber(
                                pair, std::string("maker_fee_rate_quote"))},
                           {std::string("taker"),
                            this->safeNumber(
                                pair, std::string("taker_fee_rate_quote"))},
                           {std::string("percentage"), true},
                           {std::string("tierBased"), false},
                       });
                 }
                 return result;
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    //     [
    //         "0.02501786",
    //         "0.02501786",
    //         "0.02501786",
    //         "0.02501786",
    //         "0.0000",
    //         1591488000000
    //     ]
    //
    return ccxt::list{this->safeInteger(ohlcv, 5), this->safeNumber(ohlcv, 0),
                      this->safeNumber(ohlcv, 1),  this->safeNumber(ohlcv, 2),
                      this->safeNumber(ohlcv, 3),  this->safeNumber(ohlcv, 4)};
  }

  /**
   * @method
   * @name bitbank#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see
   * https://github.com/bitbankinc/bitbank-api-docs/blob/38d6d7c6f486c793872fd4b4087a0d090a04cd0a/public-api.md#candlestick
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(since, ccxt::any{}))) {
                  if (isTrue(isEqual(limit, ccxt::any{}))) {
                    limit =
                        1000; // it doesn't have any defaults, might return 200,
                              // might 2000 (i.e.
                              // https://public.bitbank.cc/btc_jpy/candlestick/4hour/2020)
                  }
                  ccxt::any duration = this->parseTimeframe(timeframe);
                  since = subtract(this->milliseconds(),
                                   multiply(multiply(duration, 1000), limit));
                }
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any market = this->market(symbol);
                ccxt::any request = ccxt::dict{
                    {std::string("pair"),
                     ::getValue(market, std::string("id"))},
                    {std::string("candletype"),
                     this->safeString(this->timeframes, timeframe, timeframe)},
                    {std::string("yyyymmdd"),
                     this->yyyymmdd(since, std::string(""))},
                };
                ccxt::any response =
                    awaitValue(this->publicGetPairCandlestickCandletypeYyyymmdd(
                        this->extend(request, params)));
                //
                //     {
                //         "success":1,
                //         "data":{
                //             "candlestick":[
                //                 {
                //                     "type":"5min",
                //                     "ohlcv":[
                //                         ["0.02501786","0.02501786","0.02501786","0.02501786","0.0000",1591488000000],
                //                         ["0.02501747","0.02501953","0.02501747","0.02501953","0.3017",1591488300000],
                //                         ["0.02501762","0.02501762","0.02500392","0.02500392","0.1500",1591488600000],
                //                     ]
                //                 }
                //             ],
                //             "timestamp":1591508668190
                //         }
                //     }
                //
                ccxt::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::dict{});
                ccxt::any candlestick = this->safeValue(
                    data, std::string("candlestick"), ccxt::list{});
                ccxt::any first = this->safeValue(candlestick, 0, ccxt::dict{});
                ccxt::any ohlcv =
                    this->safeList(first, std::string("ohlcv"), ccxt::list{});
                return this->parseOHLCVs(ohlcv, market, timeframe, since,
                                         limit);
              })
            .share();
  }

  ccxt::any parseBalance(ccxt::any response) override {
    ccxt::any result = ccxt::dict{
        {std::string("info"), response},
        {std::string("timestamp"), ccxt::any{}},
        {std::string("datetime"), ccxt::any{}},
    };
    ccxt::any data =
        this->safeValue(response, std::string("data"), ccxt::dict{});
    ccxt::any assets =
        this->safeValue(data, std::string("assets"), ccxt::list{});
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(assets));
         postFixIncrement(i)) {
      ccxt::any balance = ::getValue(assets, i);
      ccxt::any currencyId = this->safeString(balance, std::string("asset"));
      ccxt::any code = this->safeCurrencyCode(currencyId);
      ccxt::any account = this->account();
      ::setValue(account, std::string("free"),
                 this->safeString(balance, std::string("free_amount")));
      ::setValue(account, std::string("used"),
                 this->safeString(balance, std::string("locked_amount")));
      ::setValue(account, std::string("total"),
                 this->safeString(balance, std::string("onhand_amount")));
      if (isTrue(!isEqual(code, ccxt::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

